import{_ as i,C as t,o as s,c as n,E as r,a2 as d}from"./chunks/framework.DyLyN3RJ.js";const c="/joinwell52/assets/task-transition-20261111/three-signals.en.svg",y=JSON.parse(`{"title":"The task never moved. Why does its record say it entered review?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The task never moved. Why does its record say it entered review?","date":"2026-11-11","published_date":"2026-11-11","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Which evidence proves that a task transition completed: its record, its physical location, or the caller's receipt?","summary":"A controlled submission failed while the task stayed in the active directory, yet its metadata already said review. We compared retry and lost-receipt paths to ask how an agent team proves a transition completed.","cover":"/assets/task-transition-20261111/task-threshold.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Isolated three-condition fault injection on pinned CodeFlowMu-open source; 28/28 targeted lifecycle tests; no real process crash or production incident reproduced","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-11-task-moved-after-record.md","filePath":"en/research/2026-11-11-task-moved-after-record.md","lastUpdated":1794366464000}`),l={name:"en/research/2026-11-11-task-moved-after-record.md"};function h(p,e,u,m,f,v){const a=t("ArticleCover"),o=t("ArticleTableScroll");return s(),n("div",null,[r(a,{image:"/assets/task-transition-20261111/task-threshold.cover-v1.png",kicker:"Engineering research · Task recovery",title:"The task never moved. Why does its record say it entered review?",summary:"A controlled submission failed while the task stayed in the active directory, yet its metadata already said review. We compared retry and lost-receipt paths to ask how an agent team proves a transition completed.",version:"2026-11-11",languageHref:"/zh/research/2026-11-11-task-moved-after-record",languageLabel:"中文"}),r(o,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-task-never-moved-why-does-its-record-say-it-entered-review" tabindex="-1">The task never moved. Why does its record say it entered review? <a class="header-anchor" href="#the-task-never-moved-why-does-its-record-say-it-entered-review" aria-label="Permalink to &quot;The task never moved. Why does its record say it entered review?&quot;">​</a></h1><p>You ask an AI worker to submit a task. The call errors. The task file is still in the “active” folder, so it looks as if submission never happened. But the file itself already says “review,” with a transition recording the report. <strong>Which should you trust: the error, the file&#39;s location, or the record inside it?</strong></p><p>We are building CodeFlowMu, a local multi-agent collaboration system. FCoP files hold its tasks, reports, and lifecycle history. Moving a worker&#39;s task into review looks like one action, but the runtime writes a transition, updates metadata, moves a file, and returns a response. An interruption can leave those pieces at different points.</p><p>Our <a href="https://joinwell52-ai.github.io/joinwell52/en/runtime/daily-intelligence/2026-11-11" target="_blank" rel="noreferrer">November 11 research review</a> led us to <a href="https://github.com/paperclipai/paperclip/pull/20674" target="_blank" rel="noreferrer">Paperclip&#39;s merged recovery change</a>. For its particular <code>write_document</code> operation, Paperclip stores the new revision and an idempotency receipt in one database transaction. After a restart, a saved receipt can replay the result; under that transaction guarantee, an absent receipt means the earlier write did not commit. <strong>The database is Paperclip&#39;s implementation choice; CodeFlowMu still uses FCoP task files, and this study does not propose adding a database.</strong> We tested a question in our own file-based workflow: what can our system prove after a task transition stops midway?</p><h2 id="stop-submission-at-the-threshold" tabindex="-1">Stop submission at the threshold <a class="header-anchor" href="#stop-submission-at-the-threshold" aria-label="Permalink to &quot;Stop submission at the threshold&quot;">​</a></h2><p>We invoked the real <code>LifecycleKernel.submitReview</code> from a <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/tree/ed5634c718b9e238c44bb70851020c9793546fe6" target="_blank" rel="noreferrer">pinned CodeFlowMu-open commit</a> on an isolated temporary task. A regular file occupied the target review-directory path, forcing an error after the transition metadata was written and before the task file moved. This is an injected <strong>write-before-move failure</strong>, not a reproduced production incident. We then removed the obstruction and retried the same request. Finally, we simulated losing a successful response by sending the request once more. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-11-lifecycle-atomicity/00-report.en.md" target="_blank" rel="noreferrer">evidence record</a> gives the steps and observed values.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Caller receives</th><th>Physical folder</th><th>Task metadata</th><th style="text-align:right;">Transition entries</th></tr></thead><tbody><tr><td>First call, target blocked</td><td><code>EEXIST</code></td><td>active</td><td>review, pending</td><td style="text-align:right;">1</td></tr><tr><td>Obstruction removed, same request retried</td><td>success</td><td>review</td><td>review, pending</td><td style="text-align:right;">still 1</td></tr><tr><td>Successful response presumed lost, request retried</td><td>“expected active, got review”</td><td>review</td><td>review, pending</td><td style="text-align:right;">still 1</td></tr></tbody></table><figure><img src="'+c+'" alt="Under a controlled failure, the transition record says review while the task file remains in active; retry later brings them together"><figcaption>Controlled experiment diagram: the record, physical location, and caller receipt are separate observations. The amber gap comes from our injected destination obstruction, not a production incident.</figcaption></figure><p>The first row is the trap. The call really failed, but “nothing happened” is false: the transition and target state were already recorded. The second row shows useful recovery behavior in this tested path: the retry completes the move without adding another transition. The third row points the other way. If the move succeeded but only the response was lost, a blind retry gets a stage mismatch. That error does not prove the earlier operation failed.</p><h2 id="the-record-moves-before-the-artifact" tabindex="-1">The record moves before the artifact <a class="header-anchor" href="#the-record-moves-before-the-artifact" aria-label="Permalink to &quot;The record moves before the artifact&quot;">​</a></h2><p>The source order explains the result. <code>TransitionRecorder.append</code> writes the target stage and transition event into the task file. <code>submitReview</code> then writes the pending-review fields. <code>moveTask</code> finally renames the file into the review directory. We also ran the <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/lifecycle/__tests__/LifecycleStateMachine.test.ts" target="_blank" rel="noreferrer">targeted lifecycle tests</a>: <strong>28/28 passed</strong>. Those tests cover normal transitions and several authority and repeat-call cases. They do not negate our injected failure because they exercise different conditions.</p><p>CodeFlowMu uses a project write lease to serialize these calls. Serialization does not make the metadata write, file move, and returned result one atomic transaction. In FCoP, physical location describes the current stage; the transition list records history. When they temporarily disagree, the safe observation is “needs reconciliation,” not an arbitrary choice of one as final.</p><p>Paperclip offers a useful contrast, within a narrow scope. Its transactional receipt protects <strong>that specific document write</strong>; it is no general exactly-once guarantee for tools. Our file transition cannot gain the same guarantee merely because a transition entry exists. Different storage models, same human question: <strong>how far did the previous request actually get?</strong></p><h2 id="what-proves-that-a-retry-is-the-same-operation" tabindex="-1">What proves that a retry is the same operation? <a class="header-anchor" href="#what-proves-that-a-retry-is-the-same-operation" aria-label="Permalink to &quot;What proves that a retry is the same operation?&quot;">​</a></h2><p>We confirmed a bounded intermediate state and two retry outcomes. We did not run a real process crash, a complete model session, or a production deployment, and we have no evidence of an affected user. The next engineering question is sharper: recovery must relate <strong>request identity, actual task location, transition history, and a replayable outcome</strong>. Seeing a task in review does not by itself prove that this caller&#39;s last request put it there; another authorized request might have moved it first.</p><p>CodeFlowMu&#39;s proposed target is concrete: <strong>keep FCoP task files and identify one submission by <code>task_id + report_id + actor</code>.</strong> If the file remains active and the last submission event belongs to that report, finish the move. If the file is already in review and the event matches, return the prior success to the retrying caller. If the report or actor differs, return “needs review” rather than crediting someone else&#39;s transition. Startup recovery should check the same record-versus-location split. This is a design to implement and test, not a capability established by today&#39;s probe.</p><p>The next tests ask whether that rule remains correct after a rework report changes, two authorized actors race, or a process is killed during a file write. Today&#39;s local injection cannot answer those cases.</p><p>If you build agent teams, inspect what your product says after a failed submit: “not submitted,” or “outcome being checked”? If you use one, which would you rather see when the page and task file disagree: a definite location, or an explicit notice that the last submission is being reconciled?</p>',18))])}const b=i(l,[["render",h]]);export{y as __pageData,b as default};
